const $=s=>document.querySelector(s), app=$('#app');
let state;try{state=JSON.parse(localStorage.codepath||'{}')}catch{state={}}state.done??=[];state.ratings??={};state.code??={};let lang='Python',view='dashboard',lessonIndex=0,mode='sample',worker;
const languages={Python:{icon:'Py',cls:'py',desc:'A friendly first step. A powerful next move.',file:'main.py',play:'https://pyodide.org/en/stable/console.html',count:'6 examples · 6 exercises',tag:'Great first language'},Go:{icon:'Go',cls:'go',desc:'Build fast, reliable systems that scale.',file:'main.go',play:'https://go.dev/play/',count:'6 examples · 6 exercises',tag:'Built for performance'},JavaScript:{icon:'JS',cls:'js',desc:'Bring ideas to life, from browser to backend.',file:'main.js',play:'https://developer.mozilla.org/en-US/play',count:'6 examples · 6 exercises',tag:'Made for the web'},Java:{icon:'♨',cls:'java',desc:'Strong foundations for ambitious applications.',file:'Main.java',play:'https://dev.java/playground/',count:'6 examples · 6 exercises',tag:'Enterprise ready'}};
// Every exercise has an executable output contract. Review uses test output, plus transparent style heuristics.
const topics=[['Variables & types','Beginner','Give data a name. Store a customer name and use it in a greeting.','Print exactly: Hello, Douglas!','Hello, Douglas!'],['Conditions & decisions','Beginner','A condition chooses a branch. Compare a balance with a minimum before approving an order.','For a balance of 120, print exactly: Approved','Approved'],['Loops & collections','Beginner','A collection groups values; a loop visits each item. Add the three daily sales values.','Sum 10, 20 and 30 and print exactly: 60','60'],['Functions & reuse','Intermediate','Functions give a behavior a name. Separate the tax calculation from the code that displays it.','Create a function that returns 100 multiplied by 2, then print exactly: 200','200'],['Objects & data models','Intermediate','Model a product using fields or properties so related data stays together.','Store a product named Notebook and print exactly: Notebook','Notebook'],['Errors & robust programs','Advanced','Validate inputs before calculation. Handle a zero denominator without crashing the application.','Handle division by zero and print exactly: Cannot divide by zero','Cannot divide by zero']];
const samples={Python:[`name = "Douglas"\nprint(f"Hello, {name}!")`,`balance = 120\nif balance >= 100:\n    print("Approved")\nelse:\n    print("Declined")`,`sales = [10, 20, 30]\ntotal = 0\nfor sale in sales:\n    total += sale\nprint(total)`,`def double(value):\n    return value * 2\n\nprint(double(100))`,`product = {"name": "Notebook", "price": 25}\nprint(product["name"])`,`try:\n    result = 10 / 0\n    print(result)\nexcept ZeroDivisionError:\n    print("Cannot divide by zero")`],JavaScript:[`const name = "Douglas";\nconsole.log(\`Hello, \${name}!\`);`,`const balance = 120;\nif (balance >= 100) {\n  console.log("Approved");\n} else {\n  console.log("Declined");\n}`,`const sales = [10, 20, 30];\nlet total = 0;\nfor (const sale of sales) {\n  total += sale;\n}\nconsole.log(total);`,`function double(value) {\n  return value * 2;\n}\nconsole.log(double(100));`,`const product = { name: "Notebook", price: 25 };\nconsole.log(product.name);`,`function divide(a, b) {\n  if (b === 0) throw new Error("Cannot divide by zero");\n  return a / b;\n}\ntry {\n  console.log(divide(10, 0));\n} catch (error) {\n  console.log(error.message);\n}`],Go:[`name := "Douglas"\nfmt.Printf("Hello, %s!\\n", name)`,`balance := 120\nif balance >= 100 {\n    fmt.Println("Approved")\n} else {\n    fmt.Println("Declined")\n}`,`sales := []int{10, 20, 30}\ntotal := 0\nfor _, sale := range sales {\n    total += sale\n}\nfmt.Println(total)`,`double := func(value int) int { return value * 2 }\nfmt.Println(double(100))`,`product := struct { Name string; Price int }{"Notebook", 25}\nfmt.Println(product.Name)`,`numerator, denominator := 10, 0\nif denominator == 0 {\n    fmt.Println("Cannot divide by zero")\n} else {\n    fmt.Println(numerator / denominator)\n}`],Java:[`String name = "Douglas";\nSystem.out.println("Hello, " + name + "!");`,`int balance = 120;\nif (balance >= 100) {\n    System.out.println("Approved");\n} else {\n    System.out.println("Declined");\n}`,`int[] sales = {10, 20, 30};\nint total = 0;\nfor (int sale : sales) { total += sale; }\nSystem.out.println(total);`,`java.util.function.IntUnaryOperator twice = value -> value * 2;\nSystem.out.println(twice.applyAsInt(100));`,`record Product(String name, int price) {}\nProduct product = new Product("Notebook", 25);\nSystem.out.println(product.name());`,`try {\n    int denominator = 0;\n    System.out.println(10 / denominator);\n} catch (ArithmeticException error) {\n    System.out.println("Cannot divide by zero");\n}`]};
const journeys=[['▧','Data & analytics','Python','Turn raw data into useful decisions.','Sales dashboard → CSV analysis → automated report'],['⌘','Web development','JavaScript','Build thoughtful, interactive experiences.','DOM basics → API client → accessible dashboard'],['☁','Cloud & backend','Go','Create services with speed and confidence.','CLI utility → HTTP service → concurrency'],['▦','Enterprise engineering','Java','Model complex business workflows.','Product catalog → validation → tested service'],['♡','Health technology','Python','Explore scheduling and synthetic health data.','Appointment calculator → synthetic records → validation'],['◇','Finance & operations','Java','Make reliable business calculations.','Expense tracker → decimal arithmetic → audit trail']];
function save(){localStorage.codepath=JSON.stringify(state)}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}function key(){return lang+':'+lessonIndex}function source(){let s=samples[lang][lessonIndex];if(lang==='Go')s='package main\n\nimport "fmt"\n\nfunc main() {\n'+s.split('\n').map(x=>'    '+x).join('\n')+'\n}';if(lang==='Java')s='public class Main {\n    public static void main(String[] args) {\n'+s.split('\n').map(x=>'        '+x).join('\n')+'\n    }\n}';return s}function exercise(){return lang==='Python'?'# '+topics[lessonIndex][3]+'\n\n':lang==='Go'?'package main\n\nimport "fmt"\n\nfunc main() {\n    // '+topics[lessonIndex][3]+'\n}\n':lang==='Java'?'public class Main {\n    public static void main(String[] args) {\n        // '+topics[lessonIndex][3]+'\n    }\n}':'// '+topics[lessonIndex][3]+'\n\n'}function codeKey(){return key()+':'+mode}function heading(title,sub,eye='YOUR LEARNING SPACE'){return `<div class="heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">One small step, every day. ↗</div></div>`}function languageCards(){return `<div class="languages">${Object.entries(languages).map(([n,l])=>{let done=state.done.filter(x=>x.startsWith(n+':')).length,p=Math.round(done/6*100);return `<article class="card ${n==='Python'?'selected':''}"><div class="lang-top"><div class="lang-icon ${l.cls}">${l.icon}</div><span class="tag">${n==='Python'?'POPULAR':n==='Go'?'FAST & MODERN':n==='JavaScript'?'VERSATILE':'POWERFUL'}</span></div><h3>${n}</h3><p>${l.desc}</p><div class="meta">${l.count}</div><div class="progress"><div style="width:${p}%"></div></div><div class="progress-label"><span>${done?'Your journey is underway':'Ready when you are'}</span><span>${p}%</span></div><button onclick="openLesson('${n}',0)">${done?'Continue learning':'Explore '+n} <span style="float:right">→</span></button></article>`}).join('')}</div>`}
function dashboard(){app.innerHTML=heading('A little progress. Endless possibilities.','Your next chapter starts with a line of code. Let’s make it a good one.','WELCOME BACK, DOUGLAS')+`<section class="hero"><div class="hero-copy"><span class="pill">YOUR JOURNEY STARTS HERE</span><h2>Big ideas start<br>with small beginnings.</h2><p>From your first “Hello, world” to something that matters.<br>Learn by doing, at your own pace. Always free.</p><button class="primary" onclick="openLesson('Python',0)">Start learning Python &nbsp; →</button><button class="plain" onclick="navigate('journeys')">Find your path ↗</button></div><div class="art"><div class="orb"></div><div class="code-art"><span style="color:#6e9c83"># a little curiosity goes a long way</span><br><b>def</b> build_your_future():<br>&nbsp; learn = <b>True</b><br>&nbsp; <b>while</b> learn:<br>&nbsp;&nbsp; take_a_small_step()<br>&nbsp;&nbsp; <span style="color:#e1c98d">return</span> possibilities</div><div class="float">{ }</div></div></section><div class="stats"><div class="stat"><span class="icon">▤</span><div><strong>${state.done.length}</strong><em>/ 24</em><small>Exercises completed</small></div></div><div class="stat"><span class="icon">ϟ</span><div><strong>${state.done.length*50}</strong><em>XP</em><small>Knowledge earned</small></div></div><div class="stat"><span class="icon">♧</span><div><strong>${badgeCount()}</strong><small>Achievements unlocked</small></div></div><div class="stat"><span class="icon">◎</span><div><strong>4</strong><small>Languages to explore</small></div></div></div><div class="section-title"><div><h2>One destination. Many languages.</h2><p>Start with curiosity. Choose the language that takes you there.</p></div><button class="text-btn" onclick="navigate('library')">Browse all lessons &nbsp; ↗</button></div>${languageCards()}<div class="lower"><div><div class="section-title"><div><h2>Learn for the world you work in</h2><p>Real skills. Real applications.</p></div><button class="text-btn" onclick="navigate('journeys')">All journeys ↗</button></div><div class="project"><div class="project-icon">▥</div><div><h3>From data to decisions</h3><span class="tag">DATA & ANALYTICS</span><span class="tag">PYTHON</span><p>Start with sales data. Build the foundations for your first analytics project.</p><a href="#" onclick="event.preventDefault();showJourney(0)">Explore this journey &nbsp; →</a></div></div></div><div><div class="section-title"><div><h2>Your momentum</h2><p>Every small win counts.</p></div><span>✧</span></div><div class="activity"><div class="activity-row"><span class="dot">✓</span><div>${state.done.length?'You’re building something great':'A fresh start, full of possibility'}<p>${state.done.length?'Keep learning to unlock your next badge.':'Complete your first exercise to earn 50 XP.'}</p></div></div><div class="week"><span>LEARN</span><span>PRACTICE</span><span>BUILD</span><span>REPEAT ↗</span></div></div></div></div>`}
function navigate(v){view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#breadcrumb').textContent=({dashboard:'Overview',journeys:'Learning journeys',practice:'Coding playground',library:'Example library',achievements:'Achievements',github:'GitHub workspace',cloud:'Cloud learning lab'})[v];({dashboard,journeys:journeysPage,practice,library,achievements,github,cloud:cloudPage})[v]();window.scrollTo(0,0)}document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
function openLesson(n,i,m='sample'){lang=n;lessonIndex=i;mode=m;navigate('practice')}
function practice(){let t=topics[lessonIndex];app.innerHTML=heading('A place to try. Room to grow.','Read the idea, explore an example, then make it your own.','CODING PLAYGROUND')+`<div class="tabs">${Object.keys(languages).map(n=>`<button class="${n===lang?'active':''}" onclick="openLesson('${n}',${lessonIndex})">${n}</button>`).join('')}</div><div class="workspace"><section class="lesson"><span class="level">${t[1]} · Module ${lessonIndex+1} of 6</span><h2 style="margin-top:12px">${t[0]}</h2><p>${t[2]}</p><select aria-label="Choose module" onchange="openLesson(lang,Number(this.value))">${topics.map((x,i)=>`<option value="${i}" ${i===lessonIndex?'selected':''}>${i+1}. ${x[0]}</option>`).join('')}</select><div class="tabs"><button class="${mode==='sample'?'active':''}" onclick="setMode('sample')">Example</button><button class="${mode==='exercise'?'active':''}" onclick="setMode('exercise')">Exercise</button></div><h3>${mode==='sample'?'How it works':'Your challenge'}</h3><p>${mode==='sample'?explain():t[3]}</p><p><b>Expected output</b><br><code>${esc(t[4])}</code></p><div class="notice">${['Go','Java'].includes(lang)?'Go and Java compile in an external playground. Download or copy your code, run it there, then paste the output here for an output check.':'Code runs in a separate browser worker. Reviews use output checks and basic style hints, not an AI reviewer.'}</div>${['Go','Java'].includes(lang)?`<a class="secondary" href="${languages[lang].play}" target="_blank" rel="noopener">Open ${lang} playground ↗</a><input id="manualOutput" aria-label="Paste playground output" placeholder="Paste actual output here">`:''}<div class="rating" aria-label="Rate this lesson">${[1,2,3,4,5].map(n=>`<button aria-label="Rate ${n} stars" onclick="rate(${n})">${n<=(state.ratings[key()]||0)?'★':'☆'}</button>`).join('')}</div><small style="letter-spacing:0">Your lesson rating · saved on this device</small></section><section><div class="editor"><div class="editor-head"><span>◉ &nbsp; ${languages[lang].file}</span><span>${lang} &nbsp; UTF-8</span></div><textarea id="code" aria-label="Code editor" spellcheck="false"></textarea><div class="tools"><button class="primary" id="runBtn" onclick="run(false)">▶ Run code</button><button class="secondary" id="reviewBtn" onclick="run(true)">✓ Review exercise</button><button class="secondary" onclick="resetCode()">↺ Reset</button><button class="secondary" onclick="downloadCode()">↓ Export</button></div><div class="editor-head">TERMINAL <span id="runStatus">Ready</span></div><pre class="output" id="output">Your output will appear here.</pre></div><div id="feedback" aria-live="polite"></div><div style="margin-top:16px;display:flex;justify-content:space-between"><button class="text-btn" onclick="openLesson(lang,Math.max(0,lessonIndex-1))">← Previous module</button><button class="text-btn" onclick="openLesson(lang,Math.min(5,lessonIndex+1))">Next module →</button></div></section></div>`;$('#code').value=state.code[codeKey()]??(mode==='sample'?source():exercise());$('#code').oninput=()=>{state.code[codeKey()]=$('#code').value;save()};$('#code').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const a=e.target.selectionStart,b=e.target.selectionEnd;e.target.setRangeText('    ',a,b,'end');e.target.oninput()}}}
function explain(){return ['The name variable holds text. The print statement combines a greeting, the name, and punctuation. Try changing the name and observe the output.','The comparison checks whether the balance is at least 100. Exactly one branch runs. Try a balance of 75.','Start the accumulator at zero. Each iteration adds the next sale. The final value is the sum, not the number of items.','The function accepts an input and returns a transformed value. The caller displays the returned value. Try changing the input to 25.','The data model keeps a name and price together. Access the name field without displaying the entire object.','The error path produces a clear message instead of an unhandled crash. Try a nonzero denominator to explore the successful path.'][lessonIndex]}
function setMode(m){mode=m;practice()}function resetCode(){delete state.code[codeKey()];save();practice()}function rate(n){state.ratings[key()]=n;save();practice();toast('Thanks — your '+n+' star rating is saved.')}function downloadCode(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([$('#code').value],{type:'text/plain'}));a.download=languages[lang].file;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Code exported. Ready for your repository.')}function badgeCount(){return (state.done.length>0?1:0)+(state.done.length>=6?1:0)+(new Set(state.done.map(x=>x.split(':')[0])).size>=4?1:0)+(state.done.length===24?1:0)}
async function run(review){if(review&&mode!=='exercise'){toast('Switch to Exercise and write your solution to earn XP.');return}let code=$('#code').value;$('#feedback').innerHTML='';if(['Go','Java'].includes(lang)){if(!review){window.open(languages[lang].play,'_blank','noopener');return}const out=$('#manualOutput').value;if(!out.trim()){toast('Paste the actual output from the external playground first.');return}$('#output').textContent=out;grade(out,code,true);return}$('#runBtn').disabled=$('#reviewBtn').disabled=true;$('#runStatus').textContent=lang==='Python'?'Loading Python runtime…':'Running…';$('#output').textContent='';try{let output=await execute(code,lang);$('#output').textContent=output||'(No output)';$('#runStatus').textContent='Finished';if(review)grade(output,code,false)}catch(e){$('#output').textContent=String(e.message||e);$('#runStatus').textContent='Execution failed';if(review)$('#feedback').innerHTML='<div class="feedback">The program did not finish. Read the error above, check the line indicated, and try again.</div>'}finally{$('#runBtn').disabled=$('#reviewBtn').disabled=false}}
function execute(code,language){return new Promise((resolve,reject)=>{const js=`self.onmessage=async e=>{let lines=[];try{if(e.data.language==='Python'){importScripts('https://cdn.jsdelivr.net/pyodide/v0.27.7/full/pyodide.js');let py=await loadPyodide();py.setStdout({batched:s=>lines.push(s)});py.setStderr({batched:s=>lines.push(s)});await py.runPythonAsync(e.data.code)}else{const console={log:(...a)=>lines.push(a.map(v=>typeof v==='object'?JSON.stringify(v):String(v)).join(' ')),error:(...a)=>lines.push(a.join(' ')),warn:(...a)=>lines.push(a.join(' '))};const fn=new Function('console',e.data.code);await fn(console)}self.postMessage({output:lines.join('\\n')})}catch(err){self.postMessage({error:String(err)})}}`;const url=URL.createObjectURL(new Blob([js],{type:'application/javascript'}));worker=new Worker(url);const timer=setTimeout(()=>{worker.terminate();URL.revokeObjectURL(url);reject(new Error('Execution timed out after 30 seconds. Check for an infinite loop, or retry if the Python runtime download was slow.'))},30000);worker.onmessage=e=>{clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);e.data.error?reject(new Error(e.data.error)):resolve(e.data.output)};worker.onerror=e=>{clearTimeout(timer);worker.terminate();URL.revokeObjectURL(url);reject(new Error(e.message||'Runtime could not load. Check your connection.'))};worker.postMessage({code,language})})}
function grade(out,code,manual){let pass=out.trim()===topics[lessonIndex][4],already=state.done.includes(key()),award=pass&&!manual&&!already;if(award){state.done.push(key());state.last=new Date().toISOString();save()}const hints=[];if(code.split('\n').some(l=>l.length>100))hints.push('Consider shortening lines longer than 100 characters.');if(!/\b(def|function|func|class|record)\b|=>/.test(code)&&lessonIndex===3)hints.push('This task asks for a function. Check that your solution defines and calls one.');$('#feedback').innerHTML=`<div class="feedback"><b>${pass?'✓ Output matches':'↻ Keep going'}</b>\n${pass?(manual?'Self-check only: external output is unverified, so no XP is awarded.':award?'Exercise complete. +50 XP earned!':'You already earned XP for this exercise.'):'Expected: '+esc(topics[lessonIndex][4])+'\nReceived: '+esc(out.trim()||'(empty)')}\n${esc(hints.join('\n')||'Style hint: use meaningful names and keep one clear responsibility per function.')}\nThis single output check does not verify every input or enforce the learning concept.</div>`}
function journeysPage(){app.innerHTML=heading('Learn with a destination in mind.','Choose a professional path. Build transferable foundations, then take on a real project.','LEARNING JOURNEYS')+`<div class="grid2">${journeys.map((j,i)=>`<article class="card journey" onclick="showJourney(${i})" tabindex="0" onkeydown="if(event.key==='Enter')showJourney(${i})"><span class="icon">${j[0]}</span><h3>${j[1]}</h3><span class="tag">${j[2]}</span><p>${j[3]}</p><div class="meta">${j[4]}</div><button>View journey &nbsp; →</button></article>`).join('')}</div>`}
function showJourney(i){const j=journeys[i];$('#modalBody').innerHTML=`<span class="eyebrow">CAREER EXPLORATION · ${j[2]}</span><h1>${j[1]}</h1><p>${j[3]}</p><p><b>Project roadmap</b><br>${j[4]}</p><div class="notice">Start with the six foundation modules below. The project roadmap is a suggested next step; specialist project courses are not yet included.</div><div class="lesson-list">${topics.map((t,n)=>`<button onclick="$('#modal').close();openLesson('${j[2]}',${n})">${n+1}. ${t[0]} <span style="float:right">→</span></button>`).join('')}</div>`;$('#modal').showModal()}
function library(){app.innerHTML=heading('Good ideas deserve good examples.','24 explained examples and 24 practice prompts across four languages.','EXAMPLE LIBRARY')+`<input id="lessonSearch" placeholder="Search examples, e.g. functions or Python" aria-label="Search examples"><div class="grid2" id="examples"></div>`;const draw=()=>{$('#examples').innerHTML=Object.keys(languages).flatMap(n=>topics.map((t,i)=>({n,t,i}))).filter(x=>(x.n+' '+x.t.join(' ')).toLowerCase().includes($('#lessonSearch').value.toLowerCase())).map(x=>`<article class="card"><span class="tag">${x.n} · ${x.t[1]}</span><h3>${x.t[0]}</h3><p>${x.t[2]}</p><button onclick="openLesson('${x.n}',${x.i})">Open example &nbsp; →</button></article>`).join('')||'<p>No examples found. Try another topic.</p>'};$('#lessonSearch').oninput=draw;draw()}
function achievements(){const earned=[state.done.length>0,state.done.length>=6,new Set(state.done.map(x=>x.split(':')[0])).size>=4,state.done.length===24];app.innerHTML=heading('Celebrate the small wins.','Earn 50 XP for each unique Python or JavaScript exercise that passes its output check.','YOUR ACHIEVEMENTS')+`<div class="stats"><div class="stat"><strong>${state.done.length*50} XP</strong></div><div class="stat"><strong>${badgeCount()} badges</strong></div><div class="stat"><strong>${state.done.length} solved</strong></div><div class="stat"><strong>Level ${1+Math.floor(state.done.length/4)}</strong></div></div><div class="grid2">${[['🌱','First small step','Complete your first verified exercise.'],['✧','Building momentum','Complete six verified exercises.'],['◎','Language explorer','Complete an exercise in all four languages.'],['♜','Foundation builder','Complete all 24 exercises.']].map((b,i)=>`<article class="card"><div class="badge" style="opacity:${earned[i]?1:.3}">${b[0]}</div><h3>${b[1]}</h3><p>${b[2]}</p><span class="tag">${earned[i]?'UNLOCKED':'IN PROGRESS'}</span></article>`).join('')}</div><div class="notice">Progress and personal ratings stay in this browser. Go and Java use self-checks and do not award verified XP yet; badges requiring these languages remain locked. There is no shared leaderboard or account sync.</div><button class="secondary" onclick="exportProgress()">Download my progress</button>`}
function exportProgress(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='codepath-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function github(){app.innerHTML=heading('Your learning. Out in the open.','Explore public repositories and take your practice code into your next project.','GITHUB WORKSPACE')+`<div class="grid2"><section class="lesson"><span class="icon">◉</span><h2 style="margin-top:20px">Explore your GitHub</h2><p>Enter a GitHub username to load public repositories directly from GitHub.</p><label for="ghUser">GitHub username</label><input id="ghUser" placeholder="e.g. dougcardoso81" value="${esc(state.ghUser||'')}"><button class="primary" onclick="loadRepos()" id="ghLoad">Load public repositories →</button><p id="ghStatus" aria-live="polite"></p><div id="repos"></div></section><section class="lesson"><h2>A simple Git workflow</h2><p>1. Finish an exercise in the coding playground.<br>2. Click Export to download the source file.<br>3. Open a repository below and use Add file → Upload files.<br>4. Write a commit message describing what you learned.</p><div class="notice">Public repository lookup requires no sign-in. This version does not authenticate with GitHub, read private repositories, commit code, or sync progress automatically.</div><h3>Make your first learning repository</h3><p>Keep examples, notes, and projects together. A README is a great place to explain your journey.</p><a class="primary" style="display:inline-block" target="_blank" rel="noopener" href="https://github.com/new">Create repository on GitHub ↗</a></section></div>`}
async function loadRepos(){let u=$('#ghUser').value.trim();if(!/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(u)){toast('Enter a valid GitHub username.');return}$('#ghLoad').disabled=true;$('#ghStatus').textContent='Loading repositories…';$('#repos').innerHTML='';try{const r=await fetch('https://api.github.com/users/'+encodeURIComponent(u)+'/repos?sort=updated&per_page=12');if(!r.ok)throw new Error(r.status===404?'Username not found.':r.status===403?'GitHub rate limit reached. Try again later.':'GitHub is unavailable ('+r.status+').');const repos=await r.json();state.ghUser=u;save();$('#ghStatus').textContent=repos.length?'Latest public repositories':'No public repositories found.';$('#repos').innerHTML=repos.map(r=>`<a class="repo" href="https://github.com/${encodeURIComponent(u)}/${encodeURIComponent(r.name)}" target="_blank" rel="noopener"><b>${esc(r.name)} ↗</b><small>${esc(r.description||'No description')} · ${esc(r.language||'—')} · ☆ ${r.stargazers_count}</small></a>`).join('')}catch(e){$('#ghStatus').textContent=e.message}finally{$('#ghLoad').disabled=false}}
$('#searchBtn').onclick=()=>{navigate('library');$('#lessonSearch').focus()};document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();$('#searchBtn').click()}});dashboard();
